import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("MHPCO Claim Office — quote", () => {
  // Edge case: empty list
  it("empty item list → premium 5 G (only the processing fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
  });

  // Base premiums for single main items (base + 10% first insurance + 5 fee)
  it("single sword → base premium 100 G (total 100 + 10 first + 5 fee = 115)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0)).toBe(115);
  });
  it.todo("single amulet → base premium 60 G");
  it.todo("single staff → base premium 80 G");
  it.todo("single potion → base premium 40 G");

  // Components
  it.todo("single rune → base premium 25 G");
  it.todo("single moonstone → base premium 25 G");

  // Building block of 3 alike components
  it.todo("2 runes → 50 G base premium (no block)");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");

  // "Alike" components — same type only
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // Premium modifiers — item-specific
  it.todo("cursed sword adds 50% risk surcharge (50 G on base 100 G)");
  it.todo("highly enchanted sword (enchantment ≥ 5) adds 30% surcharge");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("sword with enchantment 5 and cursed → both surcharges apply");

  // Policy-wide modifiers
  it.todo("long-standing customer (≥ 2 years) receives 20% loyalty discount");
  it.todo("customer with exactly 2 years → loyalty discount applies");
  it.todo("first insurance carries 10% initial assessment surcharge");
  it.todo("15% discount on each contract after the first");

  // Processing fee
  it.todo("a 5 G processing fee is added to every premium");

  // Modifier scope on multi-item policies
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of cursed item base) → 210 G before further modifiers and fee",
  );

  // Rounding in MHPCO's favor
  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");

  // Integration examples
  it.todo(
    "newcomer with cursed sword (steel, ench 3), 0 years → premium 165 G",
  );
  it.todo(
    "long-standing customer 2nd contract: cursed sword (steel, ench 7), 3 years → premium 160 G",
  );
  it.todo(
    "first insurance surcharge applies per item regardless of customer history",
  );

  // Insurance sum / cap (exposed via quote result or claim)
  it.todo("two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("sword + amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("sword + 3 runes (block) → insurance sum 1750 G (block affects premium only)");

  // Error handling
  it.todo("unknown item type (e.g. broomstick) → throws / error");
});

describe("MHPCO Claim Office — claim", () => {
  // Standard reimbursement
  it.todo("regular sword (steel, ench 3), damage 500 G → payout 400 G (deductible 100)");
  it.todo("rune (value 250 G), damage 200 G → payout 100 G (deductible 100, no special clause)");

  // High enchantment clause
  it.todo("dragon-material sword, ench 8, damage 1000 G → payout 400 G (50% then deductible)");
  it.todo("dragon-material sword, ench 9, damage 1000 G → payout 400 G (50% wins, then deductible)");
  it.todo("dragon-material sword, ench 5, damage 800 G → payout 700 G (dragon full, then deductible)");
  it.todo("steel sword, ench 9, damage 1000 G → payout 400 G (high-ench 50%, then deductible)");

  // Deductible per damage event
  it.todo(
    "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per item)",
  );

  // Multiple items of same type
  it.todo("two swords insured, dragon damages both → each entry a separate damage with own deductible");
  it.todo("more damage entries of a type than insured → whole claim rejected (error)");

  // Cap
  it.todo("cursed sword → cap 2000 G (based on unmodified insurance value)");
  it.todo("sword cap 2000 G; first claim 1500 → payout 1400, remaining 600");
  it.todo("sword cap 2000 G; second claim 1500 → payout 600, remaining 0 (reduced to remaining cap)");

  // Rounding
  it.todo("payout calculation yielding 350.5 G → final payout 350 G (rounded down)");

  // Error handling
  it.todo("claim references item not in policy → error");
  it.todo("claim damage amount -200 → error");
});

