const COMPONENT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;

const componentsBasePremium = (count: number): number => {
  const blocks = Math.floor(count / BLOCK_SIZE);
  const remainder = count % BLOCK_SIZE;
  return blocks * BLOCK_PREMIUM + remainder * COMPONENT_PREMIUM;
};

const applyFirstInsuranceSurcharge = (amount: number): number =>
  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;

const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);

const itemsBasePremium = (items: Item[]): number => {
  const componentCount = items.filter((item) => COMPONENT_TYPES.has(item.type)).length;
  const mainItemsTotal = items
    .filter((item) => !COMPONENT_TYPES.has(item.type))
    .reduce((sum, item) => sum + basePremium(item), 0);
  return mainItemsTotal + componentsBasePremium(componentCount);
};

export const quote = (
  customer: Customer,
  items: Item[],
  contractIndex: number,
): number => {
  const base = itemsBasePremium(items);
  return roundInMhpcoFavor(applyFirstInsuranceSurcharge(base) + PROCESSING_FEE);
};

