export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;

const componentGroupPremium = (count: number): number =>
  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;

const applyFirstInsuranceSurcharge = (amount: number): number =>
  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;

const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

const isMainItem = (item: Item): boolean => !isComponent(item);

const countByType = (components: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const component of components) {
    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
  }
  return counts;
};

const componentsTotalByType = (components: Item[]): number =>
  [...countByType(components).values()].reduce(
    (total, count) => total + componentGroupPremium(count),
    0,
  );

const itemsBasePremium = (items: Item[]): number => {
  const components = items.filter(isComponent);
  const mainItems = items.filter(isMainItem);
  const mainItemsTotal = mainItems.reduce(
    (sum, item) => sum + basePremium(item),
    0,
  );
  return mainItemsTotal + componentsTotalByType(components);
};

export const quote = (
  customer: Customer,
  items: Item[],
  contractIndex: number,
): number => {
  const base = itemsBasePremium(items);
  return roundInMhpcoFavor(applyFirstInsuranceSurcharge(base) + PROCESSING_FEE);
};

export const claim = (): number => {
  return undefined as unknown as number;
};

