export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type] ?? 0;

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + insuranceValue(item), 0);

const damagePayout = (damage: Damage): number =>
  Math.max(0, damage.amount - DEDUCTIBLE);

export const claim = (
  items: Item[],
  incident: Incident,
  priorPayouts: number,
): ClaimResult => {
  const cap = insuranceSum(items) * CAP_MULTIPLIER;
  const payout = incident.damages.reduce((sum, d) => sum + damagePayout(d), 0);
  return { payout, remainingCap: cap - priorPayouts - payout };
};

