69	  const components = items.filter(isComponent);
70	  const mainItems = items.filter(isMainItem);
71	  const mainItemsTotal = mainItems.reduce(
72	    (sum, item) => sum + basePremium(item),
73	    0,
74	  );
75	  return mainItemsTotal + componentsTotalByType(components);
76	};
77	
78	const itemSurcharge = (item: Item): number => {
79	  const base = basePremium(item);
80	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
81	  const highEnchantment =
82	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
83	      ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
84	      : 0;
85	  return curse + highEnchantment;
86	};
87	
88	const itemSurcharges = (items: Item[]): number =>
89	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
90	
91	const LOYALTY_DISCOUNT_PERCENT = 20;
92	const LOYALTY_THRESHOLD_YEARS = 2;
93	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
94	
95	const loyaltyDiscount = (customer: Customer, base: number): number =>
96	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
97	    ? percentOf(base, LOYALTY_DISCOUNT_PERCENT)
98	    : 0;
99	
100	const followUpContractDiscount = (contractIndex: number, base: number): number =>
101	  contractIndex > 0 ? percentOf(base, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
102	
103	const policyModifiers = (
104	  customer: Customer,
105	  contractIndex: number,
106	  base: number,
107	): number =>
108	  firstInsuranceSurcharge(base) -
109	  loyaltyDiscount(customer, base) -
110	  followUpContractDiscount(contractIndex, base);
111	
112	const isKnownItemType = (item: Item): boolean => item.type in BASE_PREMIUMS;
113	
114	const validateItemTypes = (items: Item[]): void => {
115	  for (const item of items) {
116	    if (!isKnownItemType(item)) {
117	      throw new Error(`Unknown item type: ${item.type}`);
118	    }
119	  }
120	};
121	
122	export const quote = (
123	  customer: Customer,
124	  items: Item[],
125	  contractIndex: number,
126	): number => {
127	  validateItemTypes(items);
128	  const base = itemsBasePremium(items);
129	  const total =
130	    base +
131	    policyModifiers(customer, contractIndex, base) +
132	    itemSurcharges(items) +
133	    PROCESSING_FEE;
134	  return roundPremiumInMhpcoFavor(total);
135	};
136	
137	export interface Damage {
138	  itemType: string;
139	  amount: number;
140	}
141	
142	export interface Incident {
143	  cause: string;
144	  damages: Damage[];
145	}
146	
147	export interface ClaimResult {
148	  payout: number;
149	  remainingCap: number;
150	}
151	
152	const DEDUCTIBLE = 100;
153	const CAP_MULTIPLIER = 2;
154	
155	const INSURANCE_VALUES: Record<string, number> = {
156	  sword: 1000,
157	  amulet: 600,
158	  staff: 800,
159	  potion: 400,
160	  rune: 250,
161	  moonstone: 250,
162	};
163	
164	const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type] ?? 0;
165	
166	const insuranceSum = (items: Item[]): number =>
167	  items.reduce((sum, item) => sum + insuranceValue(item), 0);
168	
169	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
170	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
171	
172	const reimbursedAmount = (item: Item, amount: number): number =>
173	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
174	    ? percentOf(amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
175	    : amount;
176	
177	const damagePayout = (damage: Damage, item: Item): number =>
178	  Math.max(0, reimbursedAmount(item, damage.amount) - DEDUCTIBLE);
179	
180	const insuredItemFor = (items: Item[], damage: Damage): Item =>
181	  items.find((item) => item.type === damage.itemType) as Item;
182	
183	const totalDamagePayout = (items: Item[], damages: Damage[]): number =>
184	  damages.reduce(
185	    (sum, damage) => sum + damagePayout(damage, insuredItemFor(items, damage)),
186	    0,
187	  );
188	
189	const validateDamageAmounts = (damages: Damage[]): void => {
190	  for (const damage of damages) {
191	    if (damage.amount < 0) {
192	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
193	    }
194	  }
195	};
196	
197	const validateDamageCounts = (items: Item[], damages: Damage[]): void => {
198	  const insuredCounts = countByType(items);
199	  const damageCounts = new Map<string, number>();
200	  for (const damage of damages) {
201	    const next = (damageCounts.get(damage.itemType) ?? 0) + 1;
202	    if (next > (insuredCounts.get(damage.itemType) ?? 0)) {
203	      throw new Error(
204	        `More ${damage.itemType} damages than insured items in the policy`,
205	      );
206	    }
207	    damageCounts.set(damage.itemType, next);
208	  }
209	};
210	
211	const validateIncident = (items: Item[], incident: Incident): void => {
212	  validateDamageAmounts(incident.damages);
213	  validateDamageCounts(items, incident.damages);
214	};
215	
216	export const claim = (
217	  items: Item[],
218	  incident: Incident,
219	  priorPayouts: number,
220	): ClaimResult => {
221	  validateIncident(items, incident);
222	  const cap = insuranceSum(items) * CAP_MULTIPLIER;
223	  const remainingBefore = cap - priorPayouts;
224	  const rawPayout = totalDamagePayout(items, incident.damages);
225	  const payout = Math.min(roundPayoutInMhpcoFavor(rawPayout), remainingBefore);
226	  return { payout, remainingCap: remainingBefore - payout };
227	};

